/* GUIDON service worker.
 *
 * The app is one large self-contained HTML file, so the caching model is
 * deliberately simple: precache the shell on install, serve it cache-first,
 * and treat a new build as a whole new cache generation.
 *
 * VERSION is rewritten at build time with a content hash of index.html, so a
 * changed build always produces a new cache name and always triggers the
 * update flow. Never edit it by hand.
 */
const VERSION = "__GUIDON_BUILD__";
const CACHE = "guidon-" + VERSION;

/* Everything needed to boot with the network switched off.
 *
 * Generated by tools/build.mjs at build time, from tools/icon-spec.mjs (the
 * icon set - the same single list make-icons.mjs renders from and build.mjs
 * already uses for the platform <link> tags/manifest.webmanifest icons)
 * plus build.mjs's own PDF-extraction output (pdf-lib.js/da4856.js, written
 * to web/assets/ during that same build - see build.mjs step 3's header
 * comment for why exactly those two are precached, a Soldier must be able
 * to export a counseling form with no signal, while the much larger
 * Reference Library source PDFs deliberately are not, step 3b).
 *
 * Do NOT hand-edit this list. It used to be exactly that - a 4th
 * independently hand-typed copy of the same icon set - and it had already
 * drifted out from under the other three: icon-48.png shipped and was
 * linked from a real <link rel="icon" sizes="48x48"> tag, but was never
 * added here, so it loaded over the network on first boot instead of being
 * available offline immediately (see verify.mjs "[2b] sw.js PRECACHE
 * completeness", which now regression-guards this). Edit icon-spec.mjs or
 * build.mjs's PDF-extraction list instead, then rerun `npm run build`.
 */
const PRECACHE = JSON.parse("__GUIDON_PRECACHE_JSON__");

/* The app's own page: the folder the worker controls, and index.html in it.
 * Worked out from the worker's own address so it is right wherever the app is
 * hosted (the site root, or a sub-folder such as a Pages project). */
const SCOPE_PATH = new URL("./", self.location).pathname;
const OWN_DOCUMENT_PATHS = [SCOPE_PATH, new URL("./index.html", self.location).pathname];
function isOwnDocument(url) {
  return OWN_DOCUMENT_PATHS.includes(url.pathname);
}

// The one entry the fetch handler's navigation path depends on cache-first
// (see "req.mode === navigate" below) - if this specifically didn't cache,
// the install must not be accepted as successful.
const CRITICAL = ["./index.html"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      let criticalOk = true;
      // Individually, so one missing optional icon cannot fail the whole install
      // and leave the app with no offline capability at all - but track the
      // one entry that actually matters (index.html) separately: this used
      // to swallow that failure the same as an icon's, so install() could
      // report success on a transient network blip while the critical shell
      // silently never made it into the cache.
      await Promise.all(
        PRECACHE.map(async (url) => {
          try {
            const res = await fetch(new Request(url, { cache: "reload" }));
            if (res.ok) { await cache.put(url, res); }
            else if (CRITICAL.includes(url)) { criticalOk = false; }
          } catch (e) {
            if (CRITICAL.includes(url)) criticalOk = false;
            /* non-fatal for everything else: shell still caches */
          }
        })
      );
      if (!criticalOk) {
        // Don't accept this install. Failing here (rather than resolving)
        // means the browser treats install as failed: this cache generation
        // is discarded and any previously-working service worker (and its
        // cache) stays active and serving in the meantime - strictly safer
        // than silently accepting an incomplete new generation.
        try { await caches.delete(CACHE); } catch (e) {}
        throw new Error("GUIDON SW install: critical precache entry failed (" + CRITICAL.join(",") + ")");
      }
      // Deliberately NOT skipWaiting() here. The page decides when to activate a
      // new version, so a Soldier mid-drill is never swapped out from under.
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((n) => n.startsWith("guidon-") && n !== CACHE).map((n) => caches.delete(n))
      );
      await self.clients.claim();
    })()
  );
});

/* The page posts this after the user accepts an update prompt. */
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
  if (event.data && event.data.type === "GET_VERSION") {
    event.ports && event.ports[0] && event.ports[0].postMessage({ version: VERSION });
  }
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;

  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // app makes no cross-origin requests

  // Navigations to the APP'S OWN page always resolve to the cached shell
  // first. This is what makes the app open instantly and work with no signal.
  //
  // Only the app's own page, though. This used to answer EVERY navigation with
  // index.html, and a PDF opened in a frame or a tab is a navigation too: the
  // Library's "Original PDF" view (and its "Open in a new tab" link) showed
  // GUIDON itself, a second copy of the app inside the first, where the
  // regulation should have been. Any other same-origin navigation goes to the
  // generic handler below, which serves it from the saved copy or the network.
  if (req.mode === "navigate" && isOwnDocument(url)) {
    event.respondWith(
      (async () => {
        const cached = await caches.match("./index.html", { ignoreSearch: true });
        if (cached) return cached;
        try {
          return await fetch(req);
        } catch (e) {
          return new Response("<h1>GUIDON is offline and not yet cached.</h1>", {
            status: 503,
            headers: { "content-type": "text/html; charset=utf-8" },
          });
        }
      })()
    );
    return;
  }

  event.respondWith(
    (async () => {
      const cached = await caches.match(req, { ignoreSearch: true });
      if (cached) return cached;
      try {
        const res = await fetch(req);
        // Only a whole, plain 200 is saved: a partial (206) answer to a ranged
        // request cannot be stored, and a half file must never stand in for
        // the real one when the signal is gone.
        if (res && res.status === 200 && res.type === "basic") {
          const cache = await caches.open(CACHE);
          cache.put(req, res.clone()).catch(() => { /* storage full: the network answer still goes through */ });
        }
        return res;
      } catch (e) {
        // A document the Soldier tapped that was never opened while online:
        // say so in plain words instead of a blank page.
        if (req.mode === "navigate") {
          return new Response(
            "<!doctype html><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">" +
            "<title>Not saved yet</title><body style=\"font:16px/1.5 system-ui,sans-serif;margin:24px\">" +
            "<h1 style=\"font-size:20px\">Not saved on this device yet</h1>" +
            "<p>This document is not saved on this device yet. Connect to the internet once to open it, and it will open without a signal after that.</p>" +
            "<p>Then go back to GUIDON to keep working.</p></body>",
            { status: 503, headers: { "content-type": "text/html; charset=utf-8" } }
          );
        }
        return new Response("", { status: 504 });
      }
    })()
  );
});
